1	package com.loja.checkout.dominio;
2	
3	import com.loja.checkout.comum.Dinheiro;
4	import java.math.BigDecimal;
5	import java.util.List;
6	import org.springframework.stereotype.Service;
7	
8	/**
9	 * A parte igual em todos os casos: a ordem do cálculo. Cada etapa pergunta ao caso escolhido
10	 * (entrega, cupom, clube, pagamento, região) o que é dele, e confere o que é dele no momento
11	 * em que já tem os valores de que precisa — daí sai a ordem em que os problemas são
12	 * encontrados.
13	 */
14	@Service
15	public class CalculadoraResumo {
16	
17	    public ResumoCompra calcular(EntradaPedido entrada) {
18	        List<ItemPedido> itens = entrada.itens();
19	        NivelClube nivelClube = entrada.nivelClube();
20	        Regiao regiao = entrada.regiao();
21	
22	        BigDecimal subtotalProdutos = subtotal(itens);
23	        BigDecimal pesoKg = peso(itens);
24	
25	        ModalidadeEntrega entrega = entrada.modalidadeEntrega();
26	        if (!entrega.atende(pesoKg)) {
27	            throw new PedidoRecusadoException(CodigoErro.MODALIDADE_INDISPONIVEL);
28	        }
29	        BigDecimal frete = nivelClube.frete(entrega.custo(pesoKg));
30	
31	        BigDecimal descontoCupom = descontoCupom(entrada, new ContextoCupom(itens, subtotalProdutos, frete));
32	        BigDecimal seguro = regiao.seguro(subtotalProdutos);
33	        BigDecimal totalPedido = Dinheiro.centavos(
34	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
35	
36	        FormaPagamento pagamento = entrada.formaPagamento();
37	        int parcelas = entrada.parcelas();
38	        if (!pagamento.parcelasValidas(parcelas)) {
39	            throw new PedidoRecusadoException(CodigoErro.PARCELAMENTO_INVALIDO);
40	        }
41	        if (!pagamento.disponivel(totalPedido)) {
42	            throw new PedidoRecusadoException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
43	        }
44	        ResultadoPagamento resultado = pagamento.cobrar(totalPedido, parcelas);
45	
46	        return new ResumoCompra(
47	                subtotalProdutos,
48	                descontoCupom,
49	                frete,
50	                entrega.prazoDias(),
51	                seguro,
52	                Dinheiro.centavos(resultado.totalFinal().subtract(totalPedido)),
53	                resultado.totalFinal(),
54	                parcelas,
55	                resultado.valorParcela(),
56	                nivelClube.creditoProximaCompra(subtotalProdutos),
57	                nivelClube.brinde(subtotalProdutos));
58	    }
59	
60	    private BigDecimal descontoCupom(EntradaPedido entrada, ContextoCupom contexto) {
61	        return entrada.cupom()
62	                .map(cupom -> {
63	                    if (!cupom.aplicavel(contexto)) {
64	                        throw new PedidoRecusadoException(CodigoErro.CUPOM_NAO_APLICAVEL);
65	                    }
66	                    return cupom.desconto(contexto);
67	                })
68	                .orElse(Dinheiro.ZERO);
69	    }
70	
71	    private BigDecimal subtotal(List<ItemPedido> itens) {
72	        return Dinheiro.centavos(itens.stream()
73	                .map(ItemPedido::total)
74	                .reduce(BigDecimal.ZERO, BigDecimal::add));
75	    }
76	
77	    private BigDecimal peso(List<ItemPedido> itens) {
78	        return itens.stream()
79	                .map(ItemPedido::peso)
80	                .reduce(BigDecimal.ZERO, BigDecimal::add);
81	    }
82	}
