3	import com.loja.checkout.comum.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	
7	/**
8	 * Formas de pagamento. Cada uma tem o seu ajuste sobre o total do pedido, o seu
9	 * parcelamento permitido e as suas limitações.
10	 */
11	public enum FormaPagamento {
12	
13	    PIX {
14	        @Override
15	        public ResultadoPagamento cobrar(BigDecimal totalPedido, int parcelas) {
16	            BigDecimal desconto = Dinheiro.percentual(totalPedido, new BigDecimal("0.05"));
17	            return aVista(totalPedido.subtract(desconto));
18	        }
19	    },
20	
21	    BOLETO {
22	        private static final BigDecimal TARIFA = new BigDecimal("3.49");
23	        private static final BigDecimal TOTAL_MAXIMO = new BigDecimal("1000.00");
24	
25	        @Override
26	        public ResultadoPagamento cobrar(BigDecimal totalPedido, int parcelas) {
27	            return aVista(totalPedido.add(TARIFA));
28	        }
29	
30	        @Override
31	        public boolean disponivel(BigDecimal totalPedido) {
32	            return totalPedido.compareTo(TOTAL_MAXIMO) <= 0;
33	        }
34	    },
35	
36	    CARTAO {
37	        private static final int MAXIMO_SEM_JUROS = 3;
38	        private static final int MAXIMO_PARCELAS = 12;
39	        private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
40	
41	        @Override
42	        public boolean parcelasValidas(int parcelas) {
43	            return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
44	        }
45	
46	        @Override
47	        public ResultadoPagamento cobrar(BigDecimal totalPedido, int parcelas) {
48	            if (parcelas <= MAXIMO_SEM_JUROS) {
49	                return new ResultadoPagamento(Dinheiro.centavos(totalPedido), dividir(totalPedido, parcelas));
50	            }
51	            BigDecimal parcela = Dinheiro.centavos(tabelaPrice(totalPedido, parcelas));
52	            return new ResultadoPagamento(
53	                    Dinheiro.centavos(parcela.multiply(BigDecimal.valueOf(parcelas))), parcela);
54	        }
55	
56	        /** parcela = total × taxa ÷ (1 − (1 + taxa)^−n), como no crediário. */
57	        private BigDecimal tabelaPrice(BigDecimal totalPedido, int parcelas) {
58	            MathContext mc = MathContext.DECIMAL64;
59	            BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, mc);
60	            return totalPedido.multiply(TAXA_MENSAL).multiply(fator)
61	                    .divide(fator.subtract(BigDecimal.ONE), mc);
62	        }
63	
64	        private BigDecimal dividir(BigDecimal totalPedido, int parcelas) {
65	            return Dinheiro.centavos(
66	                    totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL64));
67	        }
68	    };
69	
70	    public abstract ResultadoPagamento cobrar(BigDecimal totalPedido, int parcelas);
71	
72	    /** Quantas parcelas esta forma aceita. */
73	    public boolean parcelasValidas(int parcelas) {
74	        return parcelas == 1;
75	    }
76	
77	    /** Se a forma existe mas não atende este pedido. */
78	    public boolean disponivel(BigDecimal totalPedido) {
79	        return true;
80	    }
81	
82	    static ResultadoPagamento aVista(BigDecimal totalFinal) {
83	        BigDecimal valor = Dinheiro.centavos(totalFinal);
84	        return new ResultadoPagamento(valor, valor);
85	    }
86	}
